mapper.select:
SELECT b.account_id, b.company_id, b.account_code, b.account_name, b.account_type,
       b.dept_id, b.bank_name, b.bank_branch, b.account_number_encrypt, b.account_tail,
       b.currency, b.opening_balance, b.current_balance, b.status,
       b.create_by, b.create_time, b.update_by, b.update_time, b.remark
FROM fin_bank_account b


        AND b.account_name LIKE CONCAT('%', #{accountName}, '%')


        AND b.account_code LIKE CONCAT('%', #{accountCode}, '%')


        AND b.account_type = #{accountType}


        AND b.status = #{status}


        AND b.account_tail = #{accountTail}

    AND b.del_flag = '0'

        AND ${params.dataScope}


ORDER BY b.account_type, b.account_code

mapper.insert:
INSERT INTO fin_bank_account (
    account_code, account_name, account_type, dept_id, bank_name, bank_branch,
    account_number_encrypt, account_tail, currency,
    opening_balance, current_balance, status, create_by, create_time, remark
) VALUES (
    #{accountCode}, #{accountName}, #{accountType}, #{deptId}, #{bankName}, #{bankBranch},
    #{accountNumberEncrypt}, #{accountTail}, #{currency},
    #{openingBalance}, #{currentBalance}, #{status}, #{createBy}, sysdate(), #{remark}
)

mapper.update:
UPDATE fin_bank_account
account_name = #{accountName}, account_type = #{accountType}, bank_name = #{bankName}, bank_branch = #{bankBranch}, account_number_encrypt = #{accountNumberEncrypt}, account_tail = #{accountTail}, currency = #{currency}, opening_balance = #{openingBalance}, status = #{status}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark},
WHERE account_id = #{accountId}

UPDATE fin_bank_account SET del_flag = '2', update_time = sysdate() WHERE account_id IN
#{id}
AND current_balance = 0

mapper.select:
SELECT f.flow_id, f.flow_no, f.company_id, f.account_id,
       (SELECT account_name FROM fin_bank_account a WHERE a.account_id = f.account_id) AS account_name,
       f.flow_date, f.period, f.dept_id, f.direction, f.biz_type, f.amount,
       f.balance_after, f.source_module, f.source_type, f.source_id, f.source_key,
       f.voucher_id, f.reconcile_status,
       f.create_by, f.create_time, f.update_by, f.update_time, f.remark
FROM fin_cash_flow f


        AND f.account_id = #{accountId}


        AND f.period = #{period}


        AND f.direction = #{direction}


        AND f.biz_type = #{bizType}


        AND f.reconcile_status = #{reconcileStatus}


        AND f.flow_date >= #{params.beginFlowDate}


        AND f.flow_date <= #{params.endFlowDate}

    AND f.del_flag = '0'

ORDER BY f.flow_date DESC, f.flow_id DESC

SELECT flow_id, flow_no, account_id, flow_date, period, direction, biz_type,
       amount, balance_after, source_module, source_type, source_id, source_key,
       reconcile_status, create_time
FROM fin_cash_flow
WHERE source_module = #{sourceModule}
  AND source_type   = #{sourceType}
  AND source_id     = #{sourceId}
  AND del_flag      = '0'
LIMIT 1
